import{z as B,x as s,o as t,c as p,q as A,j as i,D as l,d as E,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"掩模库与交换","description":"","frontmatter":{"title":"掩模库与交换","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/reticle-library-exchange.md","filePath":"litho/reticle-library-exchange.md","lastUpdated":1791063341000}'),d={name:"litho/reticle-library-exchange.md"};function D(h,a,m,c,f,u){const r=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=A('<h1 id="掩模库与交换" tabindex="-1">掩模库与交换 <a class="header-anchor" href="#掩模库与交换" aria-label="Permalink to &quot;掩模库与交换&quot;">​</a></h1><div class="epigraph"><p>扫描仪旁的库把多块掩模换成场间几秒。交换慢，产能死；交换脏，缺陷和热漂移一起进。</p><footer>—— 掩模存储与运输的机械接口见 SEMI E100（Reticle SMIF Pod）规格</footer></div><p><a href="/litho/wafer-load-prealign">上一课</a>上片。缺口是上版：库、机械手、夹持、条码。本课钉掩模库与交换，不写掩模厂制版。片有缺口当零点，版没有——它靠库与夹持的机械基准定位，交换同时欠产能与套刻两笔账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一层多版（LELE 颜色、切割）要换版。库容量、交换时间、夹持重复性进套刻与产能。 Pellicle 碰撞、颗粒从库落到版上，是轨道缺陷之外的来源。</p><p>展开：换版频度定权重——每片换版（cut 层、双大版）直接进产能公式，一批一换则摊薄。库存侧风险是放错槽位、记错朝向，靠条码/RFID 与读后核验兜底；插拔路径风险是 pellicle 刮碰与落尘——版面朝下存放挡自上而下的灰，插拔瞬间的气流扰动仍可能把颗粒带上版面。夹持不一致时，同一块版每次上架的面内位置与高度都不同，套刻与焦面各吃一份随机量。</p><p><span class="marginnote">直觉类比：版没有缺口零点，像一把没有钥匙齿的钥匙插进锁——全靠库与夹持的机械基准「记住」它的位置。每次插拔都重掷一次「定位骰子」，散布直接记在套刻账上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>条码/RFID 对配方。交换路径最短、气流不直吹版面。夹持力与 <a href="/litho/reticle-clamp">掩模夹持</a> 课一致。热：刚从库到曝光，版温未平衡会胀，要等待或补偿。</p><p>工程流程：上版前条码/RFID 与 job 里的掩模 ID 核验，防上错版；交换位与曝光位分开，插拔路径不穿主气流；库与机内同用一套基准，夹持力与支撑点照 <a href="/litho/reticle-clamp">掩模夹持</a> 的口径执行。热管理二选一：等热平衡，或用热模型前馈补掉第一场的胀量；换版时间单列进产能会计，与片流死时间分开报。</p><p><span class="marginnote">数字实例：夹持重复性若给物面 ±50 nm，4× 缩比后晶圆上就是 ±12.5 nm 的套刻随机项；翻三倍到 ±150 nm，晶圆侧就是 ±37.5 nm——几乎吃光整个套刻预算。夹持重复性是按纳米采购的指标。</span></p>',11)),(t(),i(n,null,{default:l(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIB%5B%22%E6%8E%A9%E6%A8%A1%E5%BA%93%22%5D%20--%3E%20ROB%5B%22%E6%8D%A2%E7%89%88%E6%89%8B%22%5D%0A%20%20ROB%20--%3E%20CLAMP%5B%22%E5%A4%B9%E6%8C%81%22%5D%0A%20%20CLAMP%20--%3E%20EXP%5B%22%E6%9B%9D%E5%85%89%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"换版时间的产能权重取决于频度：每片一换直接乘进 wph，每批一换则摊到几百片上——调度因此尽量把同版场排在相邻片。库策略既是排产问题也是产能问题。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"版在光路里吸收 193 nm 会热胀，库温与机内温差造成第一次场的放大率误差。交换加速度类似台，但负载是版+pellicle。",-1)),a[6]||(a[6]=e("p",null,[E("写透一点：三个子系统各管一段——库管洁净与姿态（面朝下、温控贴近机内），换版手管交接（加速度按「版+pellicle」的脆弱负载设计，比片保守），夹持管可重复性（基准转换的定位散布直接进套刻）。版在光路里吸收 193 nm 会热胀，库温与机内温差造成第一次场的放大率误差，这是「第一批头几片重点复检」的来源；夹持偏心与 "),e("a",{href:"/litho/reticle-stage-sync"},"掩模台同步"),E(" 的衔接误差表现为按版分组的套刻条带。失配形状可辨：放大率误差从场中心向外放射，夹持偏心是一次性平移，热漂随曝光场数衰减——靠形状区分病因。")],-1)),(t(),i(n,null,{default:l(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIBT%5B%22%E5%BA%93%E6%B8%A9%20vs%20%E6%9C%BA%E5%86%85%E6%B8%A9%E5%B7%AE%22%5D%20--%3E%20MAG%5B%22%E6%94%BE%E5%A4%A7%E7%8E%87%E8%AF%AF%E5%B7%AE%3A%20%E5%9C%BA%E4%B8%AD%E5%BF%83%E5%90%91%E5%A4%96%E6%94%BE%E5%B0%84%22%5D%0A%20%20CLAMPX%5B%22%E5%A4%B9%E6%8C%81%E5%81%8F%E5%BF%83%20%2F%20%E5%9F%BA%E5%87%86%E8%BD%AC%E6%8D%A2%22%5D%20--%3E%20SHIFT%5B%22%E4%B8%80%E6%AC%A1%E6%80%A7%E5%B9%B3%E7%A7%BB%2C%20%E6%8C%89%E7%89%88%E5%88%86%E7%BB%84%E6%9D%A1%E5%B8%A6%22%5D%0A%20%20HEAT%5B%22%E6%9B%9D%E5%85%89%E5%9C%BA%E9%97%B4%E7%83%AD%E5%B9%B3%E8%A1%A1%22%5D%20--%3E%20DECAY%5B%22%E8%AF%AF%E5%B7%AE%E9%9A%8F%E5%9C%BA%E6%95%B0%E8%A1%B0%E5%87%8F%22%5D%0A%20%20MAG%20--%3E%20DIAG%7B%22%E7%9C%8B%E6%8C%87%E7%BA%B9%E5%BD%A2%E7%8A%B6%E5%AE%9A%E7%97%85%E5%9B%A0%22%7D%0A%20%20SHIFT%20--%3E%20DIAG%0A%20%20DECAY%20--%3E%20DIAG%0A%20%20DIAG%20--%3E%20FIX1%5B%22%E6%B8%A9%E6%8E%A7%3A%20%E7%AD%89%E5%B9%B3%E8%A1%A1%E6%88%96%E5%89%8D%E9%A6%88%E8%A1%A5%E5%81%BF%22%5D%0A%20%20DIAG%20--%3E%20FIX2%5B%22%E5%A4%B9%E6%8C%81%E9%87%8D%E5%A4%8D%E6%80%A7%3A%20%E9%87%8D%E6%A0%A1%E6%88%96%E6%8B%92%E6%94%B6%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写掩模厂内的制版、版检与出厂运输（<a href="/litho/mask-shop-flow">掩模厂流程</a>课域），也不写 pellicle 自身的透过率与寿命账（pellicle 课）；版弯与自重下垂对焦面的影响归掩模 3D 一类。整批同版时交换时间被摊薄，本课的产能侧权重下降。</p><p><span class="marginnote">常见误区：把「第一批头几片套刻差」一律记成设备漂移去拧机器。换版后第一场的放大率误差常来自库温与机内温差，随场数自己衰减——先看指纹形状（放射、平移还是衰减），再选执行器。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>换版时间是产能；夹持与热是套刻。</li><li>库是缺陷源之一，要管气流与碰撞。</li><li>下一课机台匹配：换到另一台扫描仪，库里同一块版的放大率指纹不同。</li><li>出处：掩模台课；产能课。</li></ul>',5))])}const I=B(d,[["render",D]]);export{_ as __pageData,I as default};
